l.clue('n2',(9,1),202,pair('Registre d’essais','Trial register'),pair('Avant homologation, chaque appareil doit avoir été testé au moins une fois avec 1 ou 3. Les mesures sont conservées au banc. Comparez les résultats, puis attribuez les trois fonctions.','Before approval, test each device at least once using 1 or 3. Measurements are retained at the bench. Compare outputs, then assign the three functions.'))
l.puzzle(1,(5,13),pair('Banc des appareils inconnus','Unknown device bench'),pair('Installer la mallette. Choisir l’appareil et l’entrée, mesurer, puis attribuer une fonction à A, B et C. Le registre affiche les mesures réellement prises.','Install the kit. Choose a device and input, measure, then assign functions to A, B and C. The register shows measurements actually taken.'),'assay',[pair('Choisissez une entrée qui distingue les trois opérations.','Choose an input that distinguishes all three operations.'),pair('Avec 1, les résultats possibles sont 3 (ajouter deux), 2 (doubler) et 5 (complément à six).','With 1, possible results are 3 (add two), 2 (double) and 5 (complement to six).')],pair('Tester A, B et C avec 1. A double ; B complète à six ; C ajoute deux. Attribuer ces fonctions puis valider.','Test A, B and C with 1. A doubles; B complements to six; C adds two. Assign these functions and validate.'),[1,1,2,0,2,0,2,3,4,4],functions=[1,2,0])
