board_a=['...#S','.###.','..*..','.###.','D#...'];board_b=['....D','.#...','..#..','..*#.','S....'];starts=((0,4),(4,0));goals=((4,0),(0,4));checkpoints=((2,2),(2,3));dirs=[(0,-1),(1,0),(0,1),(-1,0)]
def duet_step(state,i):
 a,b,mask=state;positions=[]
 for actor,(pos,board) in enumerate(zip([a,b],[board_a,board_b])):
  dx,dy=dirs[i];sign=1 if actor==0 else -1;p=(pos[0]+dx*sign,pos[1]+dy*sign)
  if not(0<=p[0]<5 and 0<=p[1]<5) or board[p[1]][p[0]]=='#':p=pos
  if p==checkpoints[actor]:mask|=1<<actor
  positions.append(p)
 return (*positions,mask)
