while q:
 v,acts=q.popleft()
 if v==(*goals,3):duet_actions=acts;break
 for i in range(4):
  w=duet_step(v,i)
  if w not in seen:seen.add(w);q.append((w,acts+[i]))
assert duet_actions is not None and len(duet_actions)<=24
