# The delayed echo acts two turns later on a one-position-shifted mask.
echo_masks=[3,12,26]
def echo_step(state,action):
 lamps,q0,q1=state
 if q0>=0:
  mask=echo_masks[q0];lamps^=((mask<<1)&63)|(mask>>5)
 if action<3:lamps^=echo_masks[action]
 return lamps,q1,action if action<3 else -1
q=deque([((0,-1,-1),[])]);seen={(0,-1,-1)};echo_actions=None
while q:
 v,acts=q.popleft()
 if v==(63,-1,-1):echo_actions=acts;break
 for i in range(4):
  w=echo_step(v,i)
  if w not in seen:seen.add(w);q.append((w,acts+[i]))
assert echo_actions is not None and len(echo_actions)<=12
